func (q *Queries) ListGroupOpsRunExecutions(ctx context.Context, runID int64) ([]GroupOpsExecution, error) {
	rows, err := q.db.Query(ctx, listGroupOpsRunExecutions, runID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []GroupOpsExecution{}
	for rows.Next() {
		var i GroupOpsExecution
		if err := rows.Scan(
			&i.ID,
			&i.RunID,
			&i.PlanID,
			&i.NodeID,
			&i.PlanRevision,
			&i.NodePosition,
			&i.TargetReference,
			&i.TargetDigest,
			&i.ContentSnapshot,
			&i.ContentDigest,
			&i.MaterialSnapshot,
			&i.MaterialDigest,
			&i.ExecutionKeyDigest,
			&i.ExternalEffectID,
			&i.State,
			&i.ProviderAccepted,
			&i.DeliveryProven,
			&i.ProviderReceiptDigest,
			&i.ReconciliationEvidenceDigest,
			&i.AttemptCount,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.SenderUseridSnapshot,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

